using Lifestone.Data.Terrain;

namespace Lifestone.Data.Tests;

public sealed class TerrainSplitTests
{
    /// <summary>
    /// Reference split directions per landblock, generated by a literal Python transcription of ACE
    /// Source/ACE.Server/Physics/Common/LandblockStruct.cs ConstructPolygons (incremental seedA/seedB/magicA/magicB
    /// loop, retail float test <c>splitDir * 2.3283064e-10 &lt; 0.5</c>). One char per cell in x-major order
    /// (index = cellX * 8 + cellY); '1' = SW-to-NE diagonal.
    /// </summary>
    [Theory]
    [InlineData(0xA9, 0xB4, "1111111100111111000001111100001111100011001100111001001111011011")] // Holtburg
    [InlineData(0xA9, 0xB3, "1111111100000000111111101100001100011000011001101101100110110110")]
    [InlineData(0x00, 0x00, "1011010101010101010101011001010110110100001001000110010011001110")]
    [InlineData(0xFE, 0xFE, "0001111100000000111111001000001100111000111001111001100100110110")]
    [InlineData(0x7F, 0x80, "0111001101100111011001100010010100101101101010101010101010101001")]
    public void Split_direction_matches_ACE_reference_cells(int lbX, int lbY, string expected)
    {
        var lb = new LandblockCoord((byte)lbX, (byte)lbY);
        for (var cx = 0; cx < 8; cx++)
        {
            for (var cy = 0; cy < 8; cy++)
            {
                var want = expected[(cx * 8) + cy] == '1';
                Assert.True(want == TerrainSplit.IsSWtoNE(lb, cx, cy), $"{lb} cell ({cx},{cy}): expected SWtoNE={want}");
            }
        }
    }

    [Fact]
    public void Closed_form_matches_ACE_incremental_loop_on_a_sweep_of_landblocks()
    {
        for (var lbX = 0; lbX < 255; lbX += 7)
        {
            for (var lbY = 0; lbY < 255; lbY += 5)
            {
                var lb = new LandblockCoord((byte)lbX, (byte)lbY);
                var ace = AceConstructPolygonsSplits(lb);
                for (var cx = 0; cx < 8; cx++)
                {
                    for (var cy = 0; cy < 8; cy++)
                    {
                        Assert.Equal(ace[(cx * 8) + cy], TerrainSplit.IsSWtoNE(lb, cx, cy));
                    }
                }
            }
        }
    }

    [Fact]
    public void Bit_test_equals_retail_float_comparison()
    {
        for (var gx = 0; gx < 2040; gx += 3)
        {
            for (var gy = 0; gy < 2040; gy += 11)
            {
                var s = TerrainSplit.Hash(gx, gy);
                var retail = !(s * 2.3283064e-10 < 0.5);
                Assert.Equal(retail, TerrainSplit.IsSWtoNE(gx, gy));
            }
        }
    }

    /// <summary>
    /// Independent C# transcription of ACE LandblockStruct.ConstructPolygons (VertexPerCell = 1) used as an oracle.
    /// Returns SWtoNEcut per cell, index cellX * 8 + cellY.
    /// </summary>
    private static bool[] AceConstructPolygonsSplits(LandblockCoord lb)
    {
        unchecked
        {
            var lcoordX = lb.X * 8;
            var lcoordY = lb.Y * 8;
            var result = new bool[64];
            var seedA = (uint)(lcoordX * 214614067);
            var seedB = (uint)(lcoordX * 1109124029);
            for (var x = 0; x < 8; x++)
            {
                var idxJ = 0;
                for (var y = 0; y < 8; y++)
                {
                    var magicB = seedB;
                    var magicA = seedA + 1813693831u;
                    var splitDir = (uint)(((lcoordY + idxJ) * magicA) - magicB - 1369149221u);
                    result[(x * 8) + y] = !(splitDir * 2.3283064e-10 < 0.5f);
                    idxJ++;
                }

                seedB += 1109124029u;
                seedA += 214614067u;
            }

            return result;
        }
    }
}
